-- PT102-S2-Q17. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT102-S2-Q17$batch03$ AND q.stimulus=$batch03$Nicotine has long been known to cause heart attacks and high blood pressure. Yet a recent study has shown that the incidence of heart attacks and high blood pressure is significantly higher among cigarette smokers who do not chew tobacco than among nonsmokers exposed to an equal amount of nicotine through tobacco chewing.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, helps LEAST to resolve the apparent discrepancy described above?$batch03$ AND q.correct_choice=$batch03$D$batch03$) THEN RAISE EXCEPTION 'Question changed: PT102-S2-Q17'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT102-S2-Q17$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT102-S2-Q17'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT102-S2-Q17$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Nicotine causes heart attacks and high blood pressure, and the smokers and chewers in the study took in the same amount of nicotine.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Smokers who do not chew have significantly more heart attacks and high blood pressure than chewers who do not smoke?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$Nicotine is equal, so it cannot be the difference. The answer has to be something else that separates the two groups: another ingredient in smoke that hurts the heart, something in chewing tobacco that protects it, or a lifestyle difference like diet or exercise. Run each choice through one frame: "Smokers have more heart trouble than chewers because..."$batch03$), (3, $batch03$Goal$batch03$, $batch03$This is a "helps least" question. Four choices will name a heart-related difference between the groups. The answer will not.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT102-S2-Q17$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$Smokers exercise less. Less exercise is bad for the heart, so this is a non-nicotine difference that fits the frame.$batch03$), ($batch03$B$batch03$, $batch03$Something in chewing tobacco blunts nicotine's effect on the heart. Same nicotine, less damage for chewers.$batch03$), ($batch03$C$batch03$, $batch03$Chewers eat better. A healthier diet protects the heart, which separates the groups.$batch03$), ($batch03$D$batch03$, $batch03$Cancer is not heart attacks or blood pressure. A chemical in chewing tobacco that causes cancer says nothing about why chewers have *fewer* heart problems. If anything, it is one more harm for chewers, and it fails the frame.$batch03$), ($batch03$E$batch03$, $batch03$Something in cigarette smoke, but not in chewing tobacco, raises blood pressure. That gives smokers extra heart risk on top of the shared nicotine.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT102-S2-Q17$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
